namespace sv_520f8dd2003c4784a023e87d3904a58c.Services;

/// <summary>
/// Scoped service holding the currently selected warehouse.
/// All interactive components in the same circuit share this instance,
/// ensuring per-user isolation on Blazor Server.
/// </summary>
public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "warehouse-a";
    public string SelectedWarehouseName => Warehouses.TryGetValue(SelectedWarehouseId, out var name) ? name : "Unknown";

    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["warehouse-a"] = "Warehouse A — North",
        ["warehouse-b"] = "Warehouse B — South",
        ["warehouse-c"] = "Warehouse C — East"
    };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_520f8dd2003c4784a023e87d3904a58c.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for the current warehouse.
/// Supports polling with start/stop semantics and notifies all subscribers
/// when new data arrives — enabling cross-component updates without parent-child relationships.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired from a background thread — subscribers must wrap StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call returning 0–15
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Starts polling every 10 seconds. Multiple callers are reference-counted;
    /// polling stops only when all subscribers have called StopPolling.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _cts?.Dispose();
            _cts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAsync();

        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on stop
        }
    }

    private async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async void OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh alert data
        if (_subscriberCount > 0)
        {
            await RefreshAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

