+@inject sv_520f8dd2003c4784a023e87d3904a58c.Services.WarehouseState WarehouseState
+@inject sv_520f8dd2003c4784a023e87d3904a58c.Services.InventoryAlertService AlertService
+@implements IDisposable
+
+<PageTitle>Dashboard</PageTitle>
+
+<h1>Warehouse Dashboard</h1>
+
+<div class="card mt-3" style="max-width: 500px;">
+    <div class="card-body">
+        <h5 class="card-title">@WarehouseState.SelectedWarehouseName</h5>
+        <p class="card-text">
+            Low-stock alerts:
+            <span class="badge bg-warning text-dark fs-5">@AlertService.LowStockCount</span>
+        </p>
+        <p class="text-muted small">Refreshes every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</p>
+    </div>
+</div>
+
+@code {
+    private Action? _alertHandler;
+    private Action? _warehouseHandler;
+    private DateTime _lastUpdate = DateTime.Now;
+
+    protected override void OnInitialized()
+    {
+        _alertHandler = () => InvokeAsync(() =>
+        {
+            _lastUpdate = DateTime.Now;
+            StateHasChanged();
+        });
+
+        _warehouseHandler = () => InvokeAsync(StateHasChanged);
+
+        AlertService.OnAlertCountChanged += _alertHandler;
+        WarehouseState.OnChange += _warehouseHandler;
+
+        // Start polling when dashboard is visible
+        AlertService.StartPolling();
+    }
+
+    public void Dispose()
+    {
+        AlertService.OnAlertCountChanged -= _alertHandler;
+        WarehouseState.OnChange -= _warehouseHandler;
+
+        // Stop polling when the user leaves the page
+        AlertService.StopPolling();
+    }
+}
+

